def t(title, content): return dict(type='text', title=title, content=content)
def remember(content): return dict(type='remember', content=content)
def warning(content): return dict(type='warning', title='Безопасность и пределы вывода', content=content)
def q(question, answers, correct, explanation):
    # Deterministic presentation rotation avoids an answer-position pattern.
    shift = sum(map(ord, question)) % len(answers)
    answers = answers[shift:] + answers[:shift]
    correct = (correct-shift) % len(answers)
    return dict(type='question', question=question, answers=answers, correctAnswer=correct, explanation=explanation)
def calc(question, value, unit, explanation, tolerance=.01):
    return dict(type='calculation', question=question, correctValue=value, tolerance=tolerance,
                unit=unit, hint='Проверьте единицы и подписи шкалы.', explanation=explanation)


