def img(stem): return dict(type='image', asset=f'assets/images/oscilloscope/{stem}.png', caption=CAPTIONS[stem])
def scope(title, question, scenario, exercise, **changes):
    settings=dict(voltsPerDiv=1, millisecondsPerDiv=4, centerVoltage=2.5, triggerLevel=2.5, edge='rising', mode='normal')
    settings.update(changes)
    return dict(type='oscilloscope',title=title,question=question,scenario=scenario,exercise=exercise,initialSettings=settings)


