def main():
    OUT.mkdir(parents=True, exist_ok=True)
    summaries=[]
    for order,(title,description,minutes,blocks) in enumerate(LESSONS,1):
        identifier=f'oscilloscope_{order:02}'
        lesson=dict(id=identifier,moduleId='stage_10',order=order,title=title,description=description,
                    estimatedMinutes=minutes,completion={'type':'quiz','passingScore':80} if order==10 else {'type':'lesson'},blocks=blocks)
        filename=f'lesson_{order:02}.json'
        (OUT/filename).write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        summaries.append({**{k:lesson[k] for k in ['id','order','title','description','estimatedMinutes']},'file':filename})
    (OUT/'lessons.json').write_text(json.dumps(summaries,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    scored={'question','calculation','oscilloscope'}
    print('module 11:',len(LESSONS),'lessons /',sum(len(x[3]) for x in LESSONS),'blocks /',sum(b['type'] in scored for x in LESSONS for b in x[3]),'tasks')


if __name__=='__main__': main()
